    { category: "侨务工作", title: "全国侨务工作会议在京召开 习近平作出重要指示", date: "2026年7月27日", source: "新华社", summary: "全国侨务工作会议7月27日至28日在北京召开。会上传达了习近平总书记对侨务工作的重要指示。习近平强调，新征程上要以新时代中国特色社会主义思想为指导，全面贯彻党的侨务政策，更好凝聚侨心侨力，促进海内外中华儿女团结奋斗。王沪宁出席并讲话。", points: "重要指示：更好凝聚侨心侨力、促进海内外中华儿女团结奋斗\n核心要求：全面贯彻党的侨务政策\n工作定位：紧紧围绕党和国家工作大局\n关键表述：引导海外侨胞秉承优良传统、厚植家国情怀", examLink: "侨务工作、统一战线、海内外中华儿女团结奋斗" },
    { category: "经济政策", title: "李强主持国务院常务会议 部署下半年经济工作", date: "2026年7月31日", source: "新华社", summary: "7月31日，国务院总理李强主持召开国务院常务会议，学习贯彻习近平总书记关于上半年经济形势和做好下半年经济工作的重要讲话精神，进一步部署下半年经济工作。会议强调要坚定不移完成全年经济社会发展目标任务，更大力度激发消费潜力。", points: "核心要求：坚定不移完成全年经济社会发展目标任务\n政策导向：加快全面落实已确定的宏观政策\n消费举措：更大力度激发消费潜力\n重点领域：稳就业、稳企业、稳市场、稳预期", examLink: "宏观调控、国务院常务会议、经济社会发展目标" },
    { category: "城市更新", title: "高质量推进城市更新 建设现代化人民城市", date: "2026年8月2日", source: "新华社", summary: "习近平总书记强调，高质量推进城市更新是城市现代化建设的重要抓手，要全面践行人民城市理念，坚持问需于民、问计于民、问效于民，做深做细做实城市更新各项工作，不断增强居民群众的获得感、幸福感、安全感。", points: "核心理念：人民城市人民建、人民城市为人民\n三问三民：问需于民、问计于民、问效于民\n重点任务：做深做细做实城市更新各项工作\n目标导向：增强居民群众获得感、幸福感、安全感", examLink: "人民城市理念、城市现代化建设、新型城镇化" },
    { category: "国防科技", title: "中央军委主席习近平签署通令 给杨勇记国防科技一等功", date: "2026年8月1日", source: "新华社", summary: "中央军委主席习近平日前签署通令，给中国人民解放军91548部队杨勇记国防科技一等功。八一建军节之际，这一表彰彰显了国家对国防科技创新的高度重视。", points: "表彰对象：91548部队杨勇\n荣誉等次：国防科技一等功\n时间节点：八一建军节之际\n重要意义：彰显对国防科技创新的高度重视", examLink: "国防科技、强军兴军、建军一百年奋斗目标" },
    { category: "统一战线", title: "中共中央召开党外人士座谈会 听取经济工作意见建议", date: "2026年7月24日", source: "新华社", summary: "7月24日，中共中央在中南海召开党外人士座谈会，就当前经济形势和下半年经济工作听取各民主党派中央、全国工商联负责人和无党派人士代表的意见建议。习近平总书记主持并发表重要讲话，强调做好下半年经济工作要坚持稳中求进工作总基调，实施更加积极的财政政策和适度宽松的货币政策。", points: "政策定调：更加积极的财政政策和适度宽松的货币政策\n经济判断：顶压前行、向新向优，展现强大韧性和活力\n核心要求：加大逆周期调节力度，加力扩大内需、优化供给\n三点希望：①统一思想行动 ②积极履职尽责 ③加强思想政治引领", examLink: "多党合作和政治协商制度、统一战线、下半年经济工作、宏观调控" },
    { category: "强军兴军", title: "新华社长篇通讯：向着建军一百年奋斗目标阔步前行", date: "2026年7月30日", source: "新华社", summary: "新华社7月30日播发长篇通讯《向着建军一百年奋斗目标阔步前行——以习近平同志为核心的党中央引领人民军队书写强军兴军新篇章》，系统回顾新时代人民军队在党的领导下取得的强军兴军重大成就。", points: "核心主题：以习近平同志为核心的党中央引领人民军队\n战略目标：建军一百年奋斗目标\n重大成就：人民军队实现整体性革命性重塑\n关键举措：政治建军、改革强军、科技强军、人才强军、依法治军", examLink: "强军兴军、建军一百年奋斗目标、国防和军队现代化" }
